INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65294406', 65294406, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN MONITORING & EVALUASI PENYUSUNAN LAPORAN DAMPAK EFISIENSI ANGGARAN DAK TERHADAP KINERJA IRIGASI KOORDINASI PENYUSUNAN KEBIJAKAN,PERENCANAAN, PEMANTAUAN DAN EVALUASI DANA ALOKASI KHUSUS BIDANG IRIGASI', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 91630000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Melaksanakan analisis kinerja Dana Alokasi Khusus (DAK) Bidang Irigasi, dengan fokus pada penilaian keterkaitan antara alokasi dan pemanfaatan anggaran dengan capaian kinerja. 2. Mengidentifikasi keterkaitan antara anggaran, output, dan outcome, dalam rangka menilai tingkat efektivitas pemanfaatan anggaran DAK untuk mendukung peningkatan fungsi dan kualitas layanan irigasi. 3. Melakukan pengkajian dampak efisiensi anggaran DAK, melalui analisis perbandingan antara input anggaran dengan output dan outcome kinerja irigasi yang dihasilkan, sebagai dasar penilaian efektivitas dan efisiensi pemanfaatan anggaran. 4. Melaksanakan analisis tematik berbasis data dan bukti (evidence-based) yang mencakup aspek teknis pelaksanaan kegiatan, ketepatan waktu pelaksanaan, kualitas output infrastruktur irigasi, keberlanjutan fungsi dan umur layanan, kapasitas kelembagaan daerah, karakteristik wilayah, serta mekanisme koordinasi antar pemangku kepentingan. 5. Menyusun laporan monitoring dan evaluasi secara bertahap (termin) yang bersifat analitis dan deskriptif-evaluatif, disusun secara sistematis dan berbasis data, sebagai bahan masukan evaluatif bagi Direktorat Sumber Daya Air Kementerian PPN/Bappenas.', '1. Memiliki latar belakang Pendidikan minimal S2/Magister Kebijakan Publik atau Ekonomi. 2. Memiliki pengalaman kerja paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta termasuk pengalaman subkontrak. 3. Memiliki pengalaman kerja profesional minimal 3 (tiga) tahun. 4. Memiliki pengalaman kerja di bidang Sumber Daya Air minimal 2 (dua) tahun. 5. Memiliki pengalaman perencanaan pembangunan atau kebijakan publik. 6. Memiliki pengalaman koordinasi proyek atau program lintas bidang atau lintas level pemerintahan. 7. Memiliki pengalaman dalam proyek bersama Mitra Pembangunan. 8. Memiliki pengalaman dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu anggaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2040780);
