INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65294999', 65294999, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN TEKNIK SUMBER DAYA AIR PENYUSUNAN LAPORAN REKOMENDASI UNTUK PENINGKATAN PELAKSANAAN KEBIJAKAN SUMBER DAYA AIR MONITORING DAN EVALUASI PELAKSANAAN RENCANA PEMBANGUNAN BIDANG SUMBER DAYA AIR', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 88000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Menyusun kerangka kerja dan alur pembahasan laporan rekomendasi kebijakan sumber daya air; 2. Melakukan pengumpulan data dan informasi; 3. Mengidentifikasi permasalahan utama dalam pelaksanaan kebijakan sumber daya air, termasuk pengendalian banjir, penyediaan air baku, dan pengelolaan irigasi; 4. Mengidentifikasi tantangan teknis dalam pelaksanaan program sumber daya air; 5. Mengidentifikasi kesesuaian arah kebijakan kewilayahan dengan kondisi teknis wilayah; 6. Mengidentifikasi permasalahan operasi dan pemeliharaan infrastruktur sumber daya airyang mempengaruhi keberlanjutan pelaksanaan kebijakan; 7. Mengidentifikasi kesesuaian perencanaan dengan pelaksanaan kebijakan sumber daya air; 8. Mengidentifikasi risiko dan hambatan dalam pelaksanaan kebijakan sumber daya air; 9. Mengidentifikasi dampak permasalahan pengelolaan sumber daya air terhadap pelaksanaan kebijakan sumber daya air; 10. Menyusun bahan pertimbangan teknis dan opsi tindak lanjut berdasarkan hasil identifikasi permasalahan pengelolaan sumber daya air; 11. Melakukan penyusunan laporan monitoring dan evaluasi TA. 2026.', '1. Memiliki latar belakang Pendidikan Teknik Sipil/Teknik Pengairan/Teknik Lingkungan dengan jenjang S1 dan memiliki SKA Muda; 2. Memiliki pengalaman kerja paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak; 3. Memiliki pengalaman kerja profesional minimal 4 (empat) tahun; 4. Memiliki pengalaman kerja di bidang sumber daya air minimal 4 (empat) tahun; 5. Memiliki pengalaman koordinasi proyek/program lintas bidang di lingkungan pemerintahan; 6. Memiliki pengalaman dalam perencanaan pembangunan atau kebijakan publik; 7. Memiliki pengalaman dalam pengelolaan Proyek Strategis Nasional; 8. Memiliki sertifikat pelatihan yang terkait dengan sektor sumber daya air; 9. Memiliki pengalaman dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu anggaran', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2045987);
